\set ON_ERROR_STOP on
do $$ declare t uuid:='10000000-0000-4000-8000-000000000001';a uuid:='00000000-0000-4000-8000-000000000001';b uuid:='00000000-0000-4000-8000-000000000002';candidate uuid:='00000000-0000-4000-8000-000000000003';ids assessment_analytics_fixture_ids;sid uuid;receipt jsonb;data jsonb;report jsonb;form text;subset uuid;page jsonb;details jsonb;new_score uuid;new_run uuid;latest uuid;empty_window uuid;empty_snapshot uuid;
begin
 select * into ids from assessment_analytics_fixture_ids;
 data:=jsonb_build_object('window_id',ids.window_id,'cohort_id',null,'threshold_percent',70,'reason','Question quality analysis, not a grade decision');receipt:=assessment_analytics_command(a,t,'analytics-snapshot-001',data);sid:=(receipt->>'id')::uuid;
 if assessment_analytics_command(a,t,'analytics-snapshot-001',data)<>receipt then raise exception 'Analytics replay changed snapshot';end if;
 report:=assessment_analytics_read(a,t,'report',sid);
 if report#>>'{population,registered}'<>'7' or report#>>'{population,started}'<>'6' or report#>>'{summary,count}'<>'6' or report->>'form_count'<>'2' or jsonb_array_length(report->'items')<>0 or report->'reliability'<>'null'::jsonb then raise exception 'Mixed forms/pending populations conflated: %',report;end if;
 select value->>'form_key' into form from jsonb_array_elements(report->'forms') where value->>'sample_size'='5';
 select public.assessment_analytics_read(a,t,'report',sid,value->>'form_key') into page from jsonb_array_elements(report->'forms') where value->>'sample_size'='1';
 if not exists(select 1 from jsonb_array_elements(page->'items') where value->>'type'='ordering' and value->'options'='[]'::jsonb) then raise exception 'Unsupported ordering-option analysis was fabricated as zero counts';end if;
 report:=assessment_analytics_read(a,t,'report',sid,form,null,1);
 if (report#>>'{summary,mean_percent}')::numeric<>60 or report#>>'{summary,at_or_above_threshold}'<>'3' or abs((report#>>'{reliability,raw_alpha}')::numeric-.36)>.000001 or abs((report#>>'{items,0,item_rest_correlation}')::numeric-1)>.000001 then raise exception 'Known CTT matrix mismatch: %',report;end if;
 if report#>>'{summary,distribution,0,count}'<>'2' or report#>>'{summary,distribution,9,count}'<>'3' then raise exception 'Distribution boundary counts incorrect';end if;
 page:=assessment_analytics_read(a,t,'report',sid,form,(report#>>'{items,0,id}')::uuid,1);if jsonb_array_length(page->'items')<>1 or page#>>'{items,0,id}'=report#>>'{items,0,id}' then raise exception 'Item cursor repeated or lost a question';end if;
 details:=assessment_released_breakdown(candidate,t,ids.first_attempt);if details->>'generation'<>'1' or details#>>'{sections,0,total}'<>'0' or details::text~'"(key|prompt|response|created_by|approved_by)"' then raise exception 'Candidate saw embargoed/unreleased/private material';end if;
 insert into assessment_score_revisions(tenant_id,attempt_id,scores,status,source,approved_by) select t,ids.first_attempt,v.scores,'approved','human',b from assessment_grading_runs r join assessment_score_revisions v on v.id=r.score_revision_id where r.attempt_id=ids.first_attempt and r.generation=2 returning id into new_score;
 insert into assessment_grading_runs(tenant_id,attempt_id,generation,input_hash,scorer_version,objective_scores,policy_snapshot,status,approved_by,score_revision_id) select t,ids.first_attempt,3,repeat('d',64),'assessment.scorer.v1',scores,'{}','released',b,new_score from assessment_score_revisions where id=new_score returning id into new_run;
 insert into assessment_grading_releases(tenant_id,run_id,score_revision_id,release_at,released_by) values(t,new_run,new_score,clock_timestamp()-interval '1 second',a);
 latest:=(assessment_analytics_command(a,t,'analytics-after-regrade',data)->>'id')::uuid;
 if (assessment_analytics_read(a,t,'report',sid,form)#>>'{summary,mean_percent}')::numeric<>60 or (assessment_analytics_read(a,t,'report',latest,form)#>>'{summary,mean_percent}')::numeric<>80 then raise exception 'Released regrading mutated a historical snapshot or failed to enter a new one';end if;
 if assessment_released_breakdown(candidate,t,ids.first_attempt)->>'generation'<>'3' then raise exception 'Latest eligible candidate release not selected after regrading';end if;
 begin perform assessment_released_breakdown(b,t,ids.first_attempt);raise exception 'Foreign candidate read result details';exception when no_data_found then null;end;
 begin perform assessment_analytics_read(candidate,t,'report',sid);raise exception 'Results-only candidate read institution analytics';exception when insufficient_privilege then null;end;
 begin perform assessment_analytics_read('00000000-0000-4000-8000-000000000004',t,'report',sid);raise exception 'Foreign tenant report access accepted';exception when insufficient_privilege then null;end;
 update tenant_memberships set status='inactive' where tenant_id=t and user_id=a;
 begin perform assessment_analytics_command(a,t,'analytics-snapshot-001',data);raise exception 'Revoked analyst replayed private receipt';exception when insufficient_privilege then null;end;
 update tenant_memberships set status='active' where tenant_id=t and user_id=a;
 begin update assessment_analytics_snapshots set title='Changed' where id=sid;raise exception 'Snapshot header changed';exception when check_violation then null;end;
 begin delete from assessment_analytics_rows where snapshot_id=sid;raise exception 'Snapshot row deleted';exception when check_violation then null;end;
 data:=jsonb_set(data,'{cohort_id}',to_jsonb(ids.cohort_id));subset:=(assessment_analytics_command(a,t,'analytics-cohort-001',data)->>'id')::uuid;report:=assessment_analytics_read(a,t,'report',subset);
 if report#>>'{summary,count}'<>'3' or report#>>'{population,cohort_title}'<>'Analytics reviewed class' or report#>>'{reliability,raw_alpha}' is not null or report#>>'{items,0,item_rest_correlation}' is not null then raise exception 'Small sample or current-cohort filter invalid';end if;
 if has_function_privilege('authenticated','public.assessment_analytics_read(uuid,uuid,text,uuid,text,uuid,integer)','execute') or has_table_privilege('authenticated','assessment_analytics_rows','select') then raise exception 'Raw analytics authority leaked';end if;
 if jsonb_typeof(assessment_grading_read(candidate,t,'results'))<>'array' then raise exception 'Analytics access wrapper changed existing result contract';end if;
 empty_window:=(assessment_command(a,t,'analytics-empty-window','window.create',jsonb_build_object('assessment_version_id',(select assessment_version_id from assessment_exam_windows where id=ids.window_id),'title','Empty analytics sitting','opens_at',clock_timestamp(),'closes_at',clock_timestamp()+interval '1 hour'))->>'id')::uuid;
 empty_snapshot:=(assessment_analytics_command(a,t,'analytics-empty-snapshot',jsonb_build_object('window_id',empty_window,'cohort_id',null,'threshold_percent',0,'reason','Verify an empty released population'))->>'id')::uuid;
 report:=assessment_analytics_read(a,t,'report',empty_snapshot);
 if report#>>'{summary,count}'<>'0' or report#>'{summary,mean_percent}' is distinct from 'null'::jsonb or report#>'{summary,sd_percent}' is distinct from 'null'::jsonb or report->'forms'<>'[]'::jsonb or report->'items'<>'[]'::jsonb then raise exception 'Empty population was fabricated as a zero-score sample';end if;
end;$$;
rollback;
